import React, { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";

import * as api from "../utils/api";
import TransactionHistory from "./TransactionHistory";


// Format money
const money = (value) => {
  return `₹${Number(value || 0).toFixed(2)}`;
};


function AccountDetails() {

  const { accountId } = useParams();

  const [account, setAccount] = useState(null);
  const [transactions, setTransactions] = useState([]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");


  // Load account and transaction data
  useEffect(() => {

    const loadData = async () => {

      try {

        // Get account details
        const accountData =
          await api.fetchAccount(accountId);

        // Get transaction history
        const transactionData =
          await api.fetchTransactionHistory(accountId);

        setAccount(accountData);

        setTransactions(
          transactionData || []
        );

      } catch (error) {

        console.error(
          "ACCOUNT DETAILS ERROR:",
          error
        );

        setError(
          api.messageFromError(error)
        );

      } finally {

        setLoading(false);

      }
    };

    loadData();

  }, [accountId]);


  // =========================
  // LOADING
  // =========================

  if (loading) {

    return (
      <main className="account-details-page">

        <div className="dashboard-loading">

          <div className="spinner"></div>

          <h2>Loading Account</h2>

          <p>
            Please wait while we load your account details.
          </p>

        </div>

      </main>
    );
  }


  // =========================
  // ERROR
  // =========================

  if (error) {

    return (
      <main className="account-details-page">

        <div className="dashboard-error">

          <div className="error-icon">
            !
          </div>

          <h2>
            Unable to Load Account
          </h2>

          <p>
            {error}
          </p>

          <Link
            className="secondary button-link"
            to="/dashboard"
          >
            ← Back to Dashboard
          </Link>

        </div>

      </main>
    );
  }


  // =========================
  // ACCOUNT DETAILS
  // =========================

  if (!account) {

    return (
      <main className="account-details-page">

        <div className="dashboard-empty">

          <div className="empty-icon">
            🏦
          </div>

          <h2>
            Account Not Found
          </h2>

          <p>
            We could not find the requested account.
          </p>

          <Link
            className="primary button-link"
            to="/dashboard"
          >
            ← Back to Dashboard
          </Link>

        </div>

      </main>
    );
  }


  return (

    <main className="account-details-page">

      {/* =========================================
          HEADER
      ========================================= */}

      <div className="account-details-header">

        <span className="eyebrow">
          ACCOUNT DETAILS
        </span>

        <h1>
          {account.accountHolderName}
        </h1>

        <p>
          Manage and view your account information
        </p>

      </div>


      {/* =========================================
          BACK BUTTON
      ========================================= */}

      <div className="action-row">

        <Link
          className="secondary button-link"
          to="/dashboard"
        >
          ← Back to Dashboard
        </Link>

      </div>


      {/* =========================================
          ACCOUNT SUMMARY
      ========================================= */}

      <section className="detail-card">


        {/* Account Number */}

        <div className="detail-item">

          <div className="detail-label">
            Account Number
          </div>

          <strong>
            {account.accountNumber}
          </strong>

        </div>


        {/* Account Type */}

        <div className="detail-item">

          <div className="detail-label">
            Account Type
          </div>

          <strong>
            {account.accountType}
          </strong>

        </div>


        {/* Balance */}

        <div className="detail-item">

          <div className="detail-label">
            Available Balance
          </div>

          <strong className="detail-balance">
            {money(account.balance)}
          </strong>

        </div>


        {/* Created Date */}

        <div className="detail-item">

          <div className="detail-label">
            Created Date
          </div>

          <strong>
            {account.createdDate
              ? new Date(
                  account.createdDate
                ).toLocaleDateString()
              : "—"}
          </strong>

        </div>

      </section>


      {/* =========================================
          ACCOUNT OVERVIEW
      ========================================= */}

      <section className="account-overview-card">

        <h2>
          Account Overview
        </h2>


        <div className="account-overview-grid">


          {/* Status */}

          <div className="account-overview-item">

            <span>
              Status
            </span>

            <strong>
              ACTIVE
            </strong>

          </div>


          {/* Account Holder */}

          <div className="account-overview-item">

            <span>
              Account Holder
            </span>

            <strong>
              {account.accountHolderName}
            </strong>

          </div>


          {/* Account Number */}

          <div className="account-overview-item">

            <span>
              Account Number
            </span>

            <strong>
              {account.accountNumber}
            </strong>

          </div>


          {/* Account Type */}

          <div className="account-overview-item">

            <span>
              Account Type
            </span>

            <strong>
              {account.accountType}
            </strong>

          </div>


          {/* Current Balance */}

          <div className="account-overview-item">

            <span>
              Current Balance
            </span>

            <strong>
              {money(account.balance)}
            </strong>

          </div>


          {/* Created Date */}

          <div className="account-overview-item">

            <span>
              Created Date
            </span>

            <strong>
              {account.createdDate
                ? new Date(
                    account.createdDate
                  ).toLocaleDateString()
                : "—"}
            </strong>

          </div>

        </div>

      </section>


      {/* =========================================
          TRANSACTION ACTIONS
      ========================================= */}

      <div className="section-title">

        <h2>
          Quick Actions
        </h2>

      </div>


      <div className="action-row">


        <Link
          className="primary button-link"
          to={`/accounts/${accountId}/deposit`}
        >
          + Deposit
        </Link>


        <Link
          className="secondary button-link"
          to={`/accounts/${accountId}/withdraw`}
        >
          − Withdraw
        </Link>


        <Link
          className="secondary button-link"
          to={`/accounts/${accountId}/transfer`}
        >
          ⇄ Transfer
        </Link>


        <Link
          className="secondary button-link"
          to={`/accounts/${accountId}/transactions`}
        >
          View Transactions
        </Link>

      </div>


      {/* =========================================
          TRANSACTION HISTORY
      ========================================= */}

      <div className="section-title">

        <h2>
          Transaction History
        </h2>

      </div>


      <TransactionHistory
        transactions={transactions}
      />

    </main>
  );
}


export default AccountDetails;
